            <h2>Online Users</h2>
            <ul id="connectedUsers" >

            </ul>
        </div>
        <div>
            <p id="connected-user-fullname"></p>

       {listOfUsers
            .map(user => {
                return   (
                <ul>
                <li className={['user-item', user === selectedUser ? 'active':null].join(" ")} 
            onClick={(e)=>{
                setActiveUser(!activeUser)
               if(selectedUser === '') setSelectedUser(user)
